@isTest private class CurrentBaseDatacloudDtoDeterministic002Test {
    @isTest static void datacloudDtoDeterministic002Witness() {
        Datacloud.AdditionalInformationMap aim = new Datacloud.AdditionalInformationMap();
        aim.name = 'Country';
        aim.value = 'US';
        Datacloud.FieldDiff fd = new Datacloud.FieldDiff();
        fd.name = 'Name';
        fd.difference = 'Changed';
        Account rec = new Account(Name = 'Acme');

        Datacloud.MatchRecord mr = new Datacloud.MatchRecord();
        System.assertNotEquals(null, mr);
        mr.additionalinformation = new List<Datacloud.AdditionalInformationMap>{aim};
        mr.fielddiffs = new List<Datacloud.FieldDiff>{fd};
        mr.matchconfidence = 0.75;
        mr.record = rec;
        System.assertEquals(1, mr.additionalinformation.size());
        System.assertEquals(1, mr.fielddiffs.size());
        System.assertEquals(0.75, mr.matchconfidence);
        System.assertEquals(rec, mr.record);
        System.assertEquals(1, mr.getAdditionalInformation().size());
        System.assertEquals(1, mr.getFieldDiffs().size());
        System.assertEquals(0.75, mr.getMatchConfidence());
        System.assertEquals(rec, mr.getRecord());
        System.assertEquals(true, mr.equals(mr));
        System.assertNotEquals(null, mr.hashCode());
        System.assertNotEquals(null, mr.toString());

        Datacloud.MatchResult match = new Datacloud.MatchResult();
        System.assertNotEquals(null, match);
        match.entitytype = 'Account';
        match.errors = new List<Database.Error>();
        match.matchengine = 'standard';
        match.matchrecords = new List<Datacloud.MatchRecord>{mr};
        match.rule = 'Rule1';
        match.size = 1;
        match.success = true;
        System.assertEquals('Account', match.entitytype);
        System.assertEquals(0, match.errors.size());
        System.assertEquals('standard', match.matchengine);
        System.assertEquals(1, match.matchrecords.size());
        System.assertEquals('Rule1', match.rule);
        System.assertEquals(1, match.size);
        System.assertEquals(true, match.success);
        System.assertEquals('Account', match.getEntityType());
        System.assertEquals(0, match.getErrors().size());
        System.assertEquals('standard', match.getMatchEngine());
        System.assertEquals(1, match.getMatchRecords().size());
        System.assertEquals('Rule1', match.getRule());
        System.assertEquals(1, match.getSize());
        System.assertEquals(true, match.isSuccess());
        System.assertEquals(true, match.equals(match));
        System.assertNotEquals(null, match.hashCode());
        System.assertNotEquals(null, match.toString());

        System.Datacloud.AdditionalInformationMap aliasAim = new System.Datacloud.AdditionalInformationMap();
        System.Datacloud.MatchResult aliasMatch = new System.Datacloud.MatchResult();
        System.assertNotEquals(null, aliasAim);
        System.assertNotEquals(null, aliasMatch);
    }
}
